import { forwardRef } from 'react';
import { Button } from '../Button';
import { Icon } from '../Icon';
import type { PhotoCaptureProps } from './PhotoCapture.types';

import { cn } from '../../internal/cn';

/**
 * PhotoCapture.
 *
 * Figma 정의 (node 0:434 big variant):
 *   - 정사각형, border neutral-200, radius 12
 *   - src 없음: bg white, 라벨 black, 버튼 primary "촬영"
 *   - src 있음: 사진 50% opacity over black, 라벨 white, 버튼 secondary "재촬영"
 *   - 라벨과 버튼 가운데 정렬, gap 16
 */
export const PhotoCapture = forwardRef<HTMLDivElement, PhotoCaptureProps>(
  function PhotoCapture(
    { width, full, src, label, buttonLabel, onCapture, className, style, ...rest },
    ref
  ) {
    const hasPhoto = Boolean(src);
    return (
      <div
        ref={ref}
        className={cn(
          'relative overflow-clip aspect-square border border-neutral-200 rounded-lg-12',
          full ? 'w-full' : 'self-start',
          hasPhoto ? 'bg-neutral-black' : 'bg-neutral-white',
          className
        )}
        style={{ width, ...style }}
        {...rest}
      >
        {hasPhoto && (
          <img
            alt=""
            src={src}
            className="absolute inset-0 size-full object-cover opacity-50 pointer-events-none"
          />
        )}
        <div className="absolute inset-0 flex flex-col items-center justify-center gap-16">
          {label && (
            <span
              className={cn(
                'text-body-17 font-bold',
                hasPhoto ? 'text-neutral-white' : 'text-neutral-black'
              )}
            >
              {label}
            </span>
          )}
          <Button
            variant={hasPhoto ? 'secondary' : 'primary'}
            size="md"
            onClick={onCapture}
            iconLeft={<Icon name="photo_camera" size={20} filled />}
          >
            {buttonLabel ?? (hasPhoto ? '재촬영' : '촬영')}
          </Button>
        </div>
      </div>
    );
  }
);

PhotoCapture.displayName = 'IDS.PhotoCapture';
