import { forwardRef, type CSSProperties } from 'react';
import type { IconProps } from './Icon.types';

import { cn } from '../../internal/cn';

/**
 * fontsource self-host 폰트 이름은 'Material Symbols Outlined Variable'.
 * CDN 사용 케이스 호환을 위해 'Material Symbols Outlined'도 fallback chain에.
 */
const BASE_STYLE: CSSProperties = {
  fontFamily: '"Material Symbols Outlined Variable", "Material Symbols Outlined"',
  fontFeatureSettings: '"liga"',
  fontWeight: 'normal',
  fontStyle: 'normal',
  letterSpacing: 'normal',
  textTransform: 'none',
  whiteSpace: 'nowrap',
  wordWrap: 'normal',
};

/**
 * Icon — Material Symbols (Google Fonts) 기반 아이콘.
 *
 * 폰트는 index.html `<link rel="stylesheet">` 로 로드.
 *
 * 사용:
 *   <Icon name="error" size={24} filled className="text-danger" />
 */
export const Icon = forwardRef<HTMLSpanElement, IconProps>(function Icon(
  { name, size = 24, filled = false, weight = 400, className, style, ...rest },
  ref
) {
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className={cn(
        'material-symbols-outlined inline-flex items-center justify-center',
        className
      )}
      style={{
        ...BASE_STYLE,
        fontSize: size,
        width: size,
        height: size,
        lineHeight: 1,
        fontVariationSettings: `'FILL' ${filled ? 1 : 0}, 'wght' ${weight}, 'opsz' 24`,
        ...style,
      }}
      {...rest}
    >
      {name}
    </span>
  );
});
