import { forwardRef } from 'react';
import { Icon } from '../Icon';
import type { MemoProps, MemoVariant } from './Memo.types';

import { cn } from '../../internal/cn';

const VARIANT_BOX: Record<MemoVariant, string> = {
  default: 'bg-memo-bg border-memo-border',
  wait: 'bg-temp-bg border-temp',
  error: 'bg-error-bg border-danger',
};

const VARIANT_ICON_NAME: Record<MemoVariant, string> = {
  default: 'keep',
  wait: 'hourglass',
  error: 'info',
};

const VARIANT_ICON_COLOR: Record<MemoVariant, string> = {
  default: 'text-primary',
  wait: 'text-temp',
  error: 'text-danger',
};

const VARIANT_TITLE_COLOR: Record<MemoVariant, string> = {
  default: 'text-neutral-black',
  wait: 'text-neutral-black',
  error: 'text-danger',
};

/**
 * Memo.
 *
 * Figma 정의 (node 2:366 / 5:1051 / 80:1416):
 *   - w-full, radius 12, padding 16, vertical gap 8
 *   - 헤더: icon 20 + 14 SemiBold, gap 2
 *   - 본문: 16 Regular black, line-height 1.5
 *
 * variant:
 *   - default: bg-white, border primary, icon "keep", 타이틀 black
 *   - wait:    bg-temp-bg, border temp, icon "hourglass", 타이틀 black
 *   - error:   bg-error-bg, border danger, icon "info", 타이틀 danger
 */
export const Memo = forwardRef<HTMLDivElement, MemoProps>(function Memo(
  { variant = 'default', icon, title, children, className, ...rest },
  ref
) {
  return (
    <div
      ref={ref}
      className={cn(
        'flex flex-col gap-8 w-full border rounded-lg-12 p-16',
        VARIANT_BOX[variant],
        className
      )}
      {...rest}
    >
      <div className="flex items-center gap-4">
        <Icon
          name={icon ?? VARIANT_ICON_NAME[variant]}
          size={20}
          filled
          className={VARIANT_ICON_COLOR[variant]}
        />
        <span
          className={cn(
            'text-micro-14 font-semibold',
            VARIANT_TITLE_COLOR[variant]
          )}
        >
          {title}
        </span>
      </div>
      <p className="text-body-sm-16 font-regular text-neutral-black leading-base">
        {children}
      </p>
    </div>
  );
});

Memo.displayName = 'IDS.Memo';
