import { forwardRef, useRef } from 'react';
import { Radio } from '../Radio';
import type { ObdCardProps } from './ObdCard.types';

import { cn } from '../../internal/cn';

/**
 * ObdCard.
 *
 * Figma 정의 (node 5:1388 "OBD card"):
 *   - container: w-full, bg-white, border 1px, radius 12, padding 16, gap 8
 *   - selected border: primary (#25313e)
 *   - unselected border: neutral-200 (#e6e6e6)
 *   - 좌측: Radio 컴포넌트 사용
 *   - 우측: title (H3 20 Bold black) + description (15 Regular black)
 *
 * label 중첩 회피를 위해 outer 는 div + onClick 으로 처리하고,
 * 내부 input 클릭은 ref 를 통해 위임한다.
 */
export const ObdCard = forwardRef<HTMLDivElement, ObdCardProps>(function ObdCard(
  {
    name,
    value,
    checked = false,
    onChange,
    title,
    description,
    disabled = false,
    className,
    ...rest
  },
  ref
) {
  const inputRef = useRef<HTMLInputElement>(null);

  const handleClick = () => {
    if (disabled) return;
    inputRef.current?.click();
  };

  return (
    <div
      ref={ref}
      className={cn(
        'flex items-center gap-8 w-full bg-neutral-white border rounded-lg-12 p-16 select-none',
        checked ? 'border-primary' : 'border-neutral-200',
        disabled ? 'cursor-not-allowed opacity-50' : 'cursor-pointer',
        className
      )}
      onClick={handleClick}
      {...rest}
    >
      <Radio
        ref={inputRef}
        name={name}
        value={value}
        checked={checked}
        onChange={onChange}
        disabled={disabled}
      />
      <div className="flex flex-col gap-8 flex-1 min-w-0">
        <span className="text-h3-20 font-bold text-neutral-black">
          {title}
        </span>
        <span className="text-caption-15 font-regular text-neutral-black truncate">
          {description}
        </span>
      </div>
    </div>
  );
});

ObdCard.displayName = 'IDS.ObdCard';
