import {
  Children,
  Fragment,
  createContext,
  forwardRef,
  isValidElement,
  useContext,
} from 'react';
import { Divider } from '../layout/Divider';
import { cn } from '../../internal/cn';
import type {
  DetailListProps,
  DetailListVariant,
  DetailRowProps,
} from './DetailList.types';

const Ctx = createContext<DetailListVariant>('pairs');

export const DetailList = forwardRef<HTMLDivElement, DetailListProps>(
  function DetailList(
    { variant = 'pairs', className, children, ...rest },
    ref
  ) {
    const items = Children.toArray(children).filter(isValidElement);
    return (
      <Ctx.Provider value={variant}>
        <div
          ref={ref}
          className={cn(
            'flex flex-col items-start gap-12 w-full bg-neutral-white border border-neutral-200 rounded-lg-12 p-16',
            className
          )}
          {...rest}
        >
          {items.map((child, i) => (
            <Fragment key={i}>
              {child}
              {i < items.length - 1 && <Divider />}
            </Fragment>
          ))}
        </div>
      </Ctx.Provider>
    );
  }
);
DetailList.displayName = 'IDS.DetailList';

export const DetailRow = forwardRef<HTMLDivElement, DetailRowProps>(
  function DetailRow({ label, className, children, ...rest }, ref) {
    const variant = useContext(Ctx);

    if (variant === 'single') {
      return (
        <div
          ref={ref}
          className={cn(
            'w-full text-body-sm-16 font-medium text-neutral-black truncate',
            className
          )}
          {...rest}
        >
          {children}
        </div>
      );
    }

    return (
      <div
        ref={ref}
        className={cn('flex items-center gap-8 w-full', className)}
        {...rest}
      >
        {label !== undefined && (
          <span className="text-body-sm-16 font-regular text-neutral-600 shrink-0">
            {label}
          </span>
        )}
        <span className="flex-1 min-w-0 flex items-center justify-end gap-8 text-body-sm-16 font-medium text-neutral-black">
          {children}
        </span>
      </div>
    );
  }
);
DetailRow.displayName = 'IDS.DetailRow';
