import { forwardRef } from 'react';
import type { BadgeProps, BadgeVariant } from './Badge.types';

import { cn } from '../../internal/cn';

const BASE =
  'inline-flex items-center justify-center px-12 py-8 rounded-pill-999 text-micro-14 font-bold whitespace-nowrap';

const VARIANT: Record<BadgeVariant, string> = {
  default: 'bg-neutral-200 text-neutral-600',
  install: 'bg-badge-install text-neutral-white',
  service: 'bg-badge-service text-neutral-white',
  removal: 'bg-badge-removal text-danger',
  temp: 'bg-temp-bg text-temp',
};

/**
 * Badge.
 *
 * Figma 정의:
 *   - padding 12/8, radius pill (99px), text micro-14 Bold
 *   - 5 variant: default(OBD/Non-OBD) / install / service(AS) / removal(탈거) / temp(임시)
 */
export const Badge = forwardRef<HTMLSpanElement, BadgeProps>(function Badge(
  { variant = 'default', className, children, ...rest },
  ref
) {
  return (
    <span
      ref={ref}
      className={cn(BASE, VARIANT[variant], className)}
      {...rest}
    >
      {children}
    </span>
  );
});
