import { forwardRef } from 'react';
import { cn } from '../../../internal/cn';
import type { DividerProps } from './Divider.types';
import type { SpacingToken } from '../../../types';

const MY: Record<SpacingToken, string> = {
  0: 'my-0', 4: 'my-4', 8: 'my-8', 12: 'my-12', 16: 'my-16',
  24: 'my-24', 32: 'my-32', 48: 'my-48', 64: 'my-64',
};
const MX: Record<SpacingToken, string> = {
  0: 'mx-0', 4: 'mx-4', 8: 'mx-8', 12: 'mx-12', 16: 'mx-16',
  24: 'mx-24', 32: 'mx-32', 48: 'mx-48', 64: 'mx-64',
};

export const Divider = forwardRef<HTMLDivElement, DividerProps>(function Divider(
  { orientation = 'horizontal', spacing, className, style, ...rest },
  ref
) {
  const isVertical = orientation === 'vertical';

  const classes = cn(
    'bg-neutral-200 shrink-0',
    isVertical ? 'w-px self-stretch' : 'h-px w-full',
    spacing !== undefined && (isVertical ? MX[spacing] : MY[spacing]),
    className
  );

  return (
    <div
      ref={ref}
      role="separator"
      aria-orientation={orientation}
      className={classes}
      style={style}
      {...rest}
    />
  );
});
