import { forwardRef } from 'react';
import type { StepIndicatorProps } from './StepIndicator.types';

import { cn } from '../../internal/cn';

/**
 * StepIndicator.
 *
 * Figma 정의 (node 0:593):
 *   - segment height 8, radius pill, gap 4
 *   - active fill: primary (#25313e), inactive fill: neutral-200 (#e6e6e6)
 *   - active = index < current (1-indexed)
 *
 * 기본은 segment 균등 분배(flex-1). `segmentWidth` 지정 시 px 고정.
 */
export const StepIndicator = forwardRef<HTMLDivElement, StepIndicatorProps>(
  function StepIndicator(
    { total, current, segmentWidth, className, ...rest },
    ref
  ) {
    const segments = Array.from({ length: total }, (_, i) => i < current);
    return (
      <div
        ref={ref}
        role="progressbar"
        aria-valuemin={0}
        aria-valuemax={total}
        aria-valuenow={current}
        className={cn(
          'flex items-center gap-4',
          segmentWidth === undefined && 'w-full',
          className
        )}
        {...rest}
      >
        {segments.map((active, i) => (
          <span
            key={i}
            className={cn(
              'rounded-pill-999',
              segmentWidth === undefined && 'flex-1',
              active ? 'bg-primary' : 'bg-neutral-200'
            )}
            style={{
              height: 8,
              width: segmentWidth,
            }}
          />
        ))}
      </div>
    );
  }
);

StepIndicator.displayName = 'IDS.StepIndicator';
