import { forwardRef } from 'react';
import { Icon } from '../Icon';
import type { HelperTextProps, HelperTextVariant } from './HelperText.types';

import { cn } from '../../internal/cn';

const TEXT_COLOR: Record<HelperTextVariant, string> = {
  error: 'text-danger',
  success: 'text-success',
  info: 'text-info',
};

const ICON_NAME: Record<HelperTextVariant, string> = {
  error: 'error',
  success: 'check_circle',
  info: 'help',
};

/**
 * HelperText.
 *
 * Figma 정의:
 *   - icon 24, gap 2
 *   - text 14 SemiBold
 *   - 3 variant: error / success / info
 */
export const HelperText = forwardRef<HTMLDivElement, HelperTextProps>(
  function HelperText({ variant = 'info', className, children, ...rest }, ref) {
    return (
      <div
        ref={ref}
        className={cn('inline-flex items-center', TEXT_COLOR[variant], className)}
        style={{ gap: 2 }}
        {...rest}
      >
        <Icon name={ICON_NAME[variant]} size={24} filled />
        <span className="text-micro-14 font-semibold whitespace-nowrap">
          {children}
        </span>
      </div>
    );
  }
);
