import { forwardRef, type CSSProperties } from 'react';
import type { ButtonProps, ButtonSize, ButtonVariant } from './Button.types';

import { cn } from '../../internal/cn';

const BASE =
  'inline-flex items-center justify-center font-bold ' +
  'transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-primary ' +
  'disabled:cursor-not-allowed';

/**
 * Variant별 색·텍스트.
 * 단계: default / pressed(active) / disabled.
 */
const VARIANT: Record<ButtonVariant, string> = {
  primary:
    'bg-button-primary-default text-neutral-white ' +
    'active:bg-button-primary-pressed ' +
    'disabled:bg-button-primary-disabled',
  secondary:
    'bg-button-secondary-default text-neutral-600 ' +
    'active:bg-button-secondary-pressed active:text-neutral-600 ' +
    'disabled:bg-button-secondary-disabled disabled:text-neutral-400',
  outline:
    'bg-transparent border text-neutral-800 ' +
    'border-button-outline-default ' +
    'active:bg-button-outline-pressed-bg active:border-button-outline-default ' +
    'disabled:border-button-outline-disabled disabled:text-neutral-400',
  danger:
    'bg-button-danger-default text-neutral-white ' +
    'active:bg-button-danger-pressed ' +
    'disabled:bg-button-danger-disabled',
  success:
    'bg-button-success-default text-neutral-white ' +
    'active:bg-button-success-pressed ' +
    'disabled:bg-button-success-disabled',
};

/** size별 spacing/radius/text 클래스. height는 inline style로 처리 (figma 40/56). */
interface SizeMap {
  height: number;
  paddingX: string;
  paddingXIconOnly: number;
  gap: string;
  radius: string;
  text: string;
  iconSize: number;
}

const SIZE: Record<ButtonSize, SizeMap> = {
  md: {
    height: 40,
    paddingX: 'px-16',
    paddingXIconOnly: 10,
    gap: 'gap-4',
    radius: 'rounded-md-8',
    text: 'text-caption-15',
    iconSize: 20,
  },
  lg: {
    height: 56,
    paddingX: 'px-24',
    paddingXIconOnly: 16,
    gap: 'gap-8',
    radius: 'rounded-lg-12',
    text: 'text-body-17',
    iconSize: 24,
  },
};

export const Button = forwardRef<HTMLButtonElement, ButtonProps>(function Button(
  {
    variant = 'primary',
    size = 'lg',
    loading,
    disabled,
    type = 'button',
    iconLeft,
    iconRight,
    className,
    style,
    children,
    ...rest
  },
  ref
) {
  const sz = SIZE[size];
  const isIconOnly = !children && (iconLeft || iconRight);

  const sizingStyle: CSSProperties = {
    height: sz.height,
    ...(isIconOnly && { paddingLeft: sz.paddingXIconOnly, paddingRight: sz.paddingXIconOnly }),
    ...style,
  };

  return (
    <button
      ref={ref}
      type={type}
      disabled={disabled || loading}
      className={cn(
        BASE,
        sz.radius,
        sz.text,
        sz.gap,
        !isIconOnly && sz.paddingX,
        VARIANT[variant],
        className
      )}
      style={sizingStyle}
      {...rest}
    >
      {loading ? (
        <Spinner size={sz.iconSize} />
      ) : (
        iconLeft
      )}
      {children}
      {!loading && iconRight}
    </button>
  );
});

function Spinner({ size }: { size: number }) {
  return (
    <span
      className="inline-block animate-spin rounded-pill-999 border-2 border-current border-t-transparent"
      style={{ width: size, height: size }}
    />
  );
}
