import {
  forwardRef,
  useEffect,
  useRef,
  useState,
  type CSSProperties,
} from 'react';
import { Icon } from '../Icon';
import type { SelectProps } from './Select.types';

import { cn } from '../../internal/cn';

const DROPDOWN_Z = 50;

/**
 * Select — 드롭다운 (Figma 0:280 type=Select).
 *
 * Trigger: h 48, radius input-10, border, padding x 16, gap 8, 우측 arrow_drop_down.
 * Dropdown: 절대 위치 (trigger 아래), bg white, border, radius input-10, max-height 240 (overflow scroll).
 * Option: padding 12/16, hover/selected 시 neutral-100.
 */
export const Select = forwardRef<HTMLDivElement, SelectProps>(function Select(
  {
    label,
    required,
    error,
    success,
    disabled,
    options,
    value,
    onChange,
    placeholder = '선택해 주세요',
    className,
    ...rest
  },
  ref
) {
  const [open, setOpen] = useState(false);
  const rootRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    if (!open) return;
    const onDocClick = (e: MouseEvent) => {
      if (!rootRef.current?.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener('mousedown', onDocClick);
    return () => document.removeEventListener('mousedown', onDocClick);
  }, [open]);

  const selected = options.find((o) => o.value === value);
  const stateClass = error
    ? 'border-danger'
    : success
      ? 'border-success'
      : 'border-neutral-200';
  const bgClass = disabled ? 'bg-neutral-100' : 'bg-neutral-white';
  const textClass = selected
    ? disabled
      ? 'text-neutral-600'
      : 'text-neutral-black'
    : 'text-neutral-500';

  const dropdownStyle: CSSProperties = { zIndex: DROPDOWN_Z };

  return (
    <div
      ref={(node) => {
        rootRef.current = node;
        if (typeof ref === 'function') ref(node);
        else if (ref) (ref as React.MutableRefObject<HTMLDivElement | null>).current = node;
      }}
      className={cn('flex flex-col gap-8 w-full relative', className)}
      {...rest}
    >
      {label && (
        <span className="flex items-center gap-2 text-micro-14 font-regular text-neutral-600">
          <span>{label}</span>
          {required && <span className="text-danger">*</span>}
        </span>
      )}
      <button
        type="button"
        disabled={disabled}
        onClick={() => !disabled && setOpen((o) => !o)}
        className={cn(
          'flex items-center gap-8 h-[48px] px-16 border rounded-input-10 text-left',
          open && !disabled && 'shadow-[0_0_0_3px_rgba(38,57,73,0.08)]',
          stateClass,
          bgClass,
          disabled ? 'cursor-not-allowed' : 'cursor-pointer'
        )}
      >
        <span className={cn('flex-1 min-w-0 text-body-sm-16 font-regular truncate', textClass)}>
          {selected?.label ?? placeholder}
        </span>
        <Icon
          name="arrow_drop_down"
          size={24}
          className={disabled ? 'text-neutral-500' : 'text-neutral-black'}
        />
      </button>
      {open && !disabled && (
        <ul
          role="listbox"
          style={dropdownStyle}
          className="absolute left-0 right-0 top-full mt-4 max-h-[240px] overflow-y-auto bg-neutral-white border border-neutral-200 rounded-input-10 shadow-md"
        >
          {options.map((opt) => {
            const isSelected = opt.value === value;
            return (
              <li
                key={opt.value}
                role="option"
                aria-selected={isSelected}
                onClick={() => {
                  onChange?.(opt.value);
                  setOpen(false);
                }}
                className={cn(
                  'px-16 py-12 cursor-pointer text-body-sm-16 font-regular text-neutral-black',
                  isSelected ? 'bg-neutral-100' : 'hover:bg-neutral-100'
                )}
              >
                {opt.label}
              </li>
            );
          })}
        </ul>
      )}
    </div>
  );
});

Select.displayName = 'IDS.Select';
