import { forwardRef } from 'react';
import { Icon } from '../Icon';
import { StatusPill } from '../StatusPill';
import type { JobCardCompletion, JobCardProps } from './JobCard.types';

import { cn } from '../../internal/cn';

const ROW =
  'flex items-center gap-4 text-micro-14 font-regular text-neutral-600';

const DEFAULT_PREFIX: Record<JobCardCompletion['status'], string> = {
  completed: '작업 완료일',
  failed: '작업 불가일',
};

const DEFAULT_LABEL: Record<JobCardCompletion['status'], string> = {
  completed: '완료',
  failed: '작업 불가',
};

/**
 * JobCard.
 *
 * Figma 정의 (node 39:1792):
 *   - container: bg-neutral-white, border 1px neutral-200, radius lg-12, padding 16
 *   - 헤더: carModel(14 Regular), plateNumber(22 Bold), branch(16 Medium)
 *   - 우상단: badges 슬롯 (Badge 자유 조합)
 *   - 디바이더: neutral-200
 *   - 기본(tasks): calendar/location/call 3행 (16px icon + micro-14 Regular neutral-600)
 *   - completion 모드(history): 1행만, 우측에 StatusPill (status별 색·아이콘)
 */
export const JobCard = forwardRef<HTMLDivElement, JobCardProps>(function JobCard(
  {
    carModel,
    plateNumber,
    branch,
    date,
    address,
    phone,
    badges,
    completion,
    className,
    ...rest
  },
  ref
) {
  const isCompletion = Boolean(completion);
  const displayDate = completion ? completion.date : date;
  const datePrefix = completion
    ? (completion.datePrefix ?? DEFAULT_PREFIX[completion.status])
    : '작업 요청일';
  const pillLabel = completion
    ? (completion.label ?? DEFAULT_LABEL[completion.status])
    : null;

  return (
    <div
      ref={ref}
      className={cn(
        'flex flex-col gap-16 w-full bg-neutral-white border border-neutral-200 rounded-lg-12 p-16',
        className
      )}
      {...rest}
    >
      <div className="flex items-start justify-between gap-8">
        <div className="flex flex-col min-w-0">
          <span className="text-micro-14 font-regular text-neutral-black">
            {carModel}
          </span>
          <span className="text-h2-22 font-bold text-neutral-black">
            {plateNumber}
          </span>
          <span className="text-body-sm-16 font-medium text-neutral-black">
            {branch}
          </span>
        </div>
        {badges ? (
          <div className="flex items-center gap-4 shrink-0">{badges}</div>
        ) : null}
      </div>

      <div className="border-t border-neutral-200" />

      <div className="flex flex-col gap-4">
        <div className="flex items-center justify-between gap-8 w-full">
          <div className={cn(ROW, 'min-w-0')}>
            <Icon name="calendar_today" size={16} filled />
            <span className="truncate">
              {datePrefix}: {displayDate}
            </span>
          </div>
          {isCompletion && completion && (
            <StatusPill status={completion.status}>{pillLabel}</StatusPill>
          )}
        </div>
        {!isCompletion && address && (
          <div className={ROW}>
            <Icon name="location_on" size={16} filled />
            <span>{address}</span>
          </div>
        )}
        {!isCompletion && phone && (
          <div className={ROW}>
            <Icon name="call" size={16} filled />
            <span>{phone}</span>
          </div>
        )}
      </div>
    </div>
  );
});

JobCard.displayName = 'IDS.JobCard';
