import {
  forwardRef,
  useEffect,
  useMemo,
  useRef,
  useState,
} from 'react';
import { Icon } from '../Icon';
import type { DatePickerProps } from './DatePicker.types';

import { cn } from '../../internal/cn';

const DAY_LABELS = ['일', '월', '화', '수', '목', '금', '토'];
const DROPDOWN_Z = 50;

const pad = (n: number) => n.toString().padStart(2, '0');
const formatIso = (y: number, m: number, d: number) =>
  `${y}-${pad(m + 1)}-${pad(d)}`;

const parseIso = (s?: string) => {
  if (!s) return null;
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s);
  if (!m) return null;
  return { year: +m[1], month: +m[2] - 1, day: +m[3] };
};

/**
 * DatePicker — 캘린더 팝업 (Figma 0:280 type=Datepicker).
 *
 * Trigger: h 48, radius input-10, border, padding x 16, gap 8, 우측 calendar_today.
 * Calendar popup: 절대 위치, bg white, border, radius input-10.
 * 헤더: < YYYY-MM > / 7일 라벨 / 6주 그리드.
 */
export const DatePicker = forwardRef<HTMLDivElement, DatePickerProps>(
  function DatePicker(
    {
      label,
      required,
      error,
      success,
      disabled,
      value,
      onChange,
      placeholder = 'YYYY-MM-DD',
      className,
      ...rest
    },
    ref
  ) {
    const [open, setOpen] = useState(false);
    const rootRef = useRef<HTMLDivElement | null>(null);
    const parsed = parseIso(value);
    const today = new Date();
    const [viewYear, setViewYear] = useState(parsed?.year ?? today.getFullYear());
    const [viewMonth, setViewMonth] = useState(parsed?.month ?? today.getMonth());

    useEffect(() => {
      if (!open) return;
      const onDocClick = (e: MouseEvent) => {
        if (!rootRef.current?.contains(e.target as Node)) setOpen(false);
      };
      document.addEventListener('mousedown', onDocClick);
      return () => document.removeEventListener('mousedown', onDocClick);
    }, [open]);

    useEffect(() => {
      if (open && parsed) {
        setViewYear(parsed.year);
        setViewMonth(parsed.month);
      }
    }, [open]);

    const cells = useMemo(() => {
      const firstDow = new Date(viewYear, viewMonth, 1).getDay();
      const daysInMonth = new Date(viewYear, viewMonth + 1, 0).getDate();
      const result: { day: number; inMonth: boolean }[] = [];
      for (let i = 0; i < firstDow; i++) result.push({ day: 0, inMonth: false });
      for (let d = 1; d <= daysInMonth; d++) result.push({ day: d, inMonth: true });
      while (result.length % 7 !== 0) result.push({ day: 0, inMonth: false });
      return result;
    }, [viewYear, viewMonth]);

    const stateClass = error
      ? 'border-danger'
      : success
        ? 'border-success'
        : 'border-neutral-200';
    const bgClass = disabled ? 'bg-neutral-100' : 'bg-neutral-white';
    const textClass = value
      ? disabled
        ? 'text-neutral-600'
        : 'text-neutral-black'
      : 'text-neutral-500';

    const moveMonth = (delta: number) => {
      let y = viewYear;
      let m = viewMonth + delta;
      if (m < 0) { m = 11; y--; }
      if (m > 11) { m = 0; y++; }
      setViewYear(y);
      setViewMonth(m);
    };

    return (
      <div
        ref={(node) => {
          rootRef.current = node;
          if (typeof ref === 'function') ref(node);
          else if (ref) (ref as React.MutableRefObject<HTMLDivElement | null>).current = node;
        }}
        className={cn('flex flex-col gap-8 w-full relative', className)}
        {...rest}
      >
        {label && (
          <span className="flex items-center gap-2 text-micro-14 font-regular text-neutral-600">
            <span>{label}</span>
            {required && <span className="text-danger">*</span>}
          </span>
        )}
        <button
          type="button"
          disabled={disabled}
          onClick={() => !disabled && setOpen((o) => !o)}
          className={cn(
            'flex items-center gap-8 h-[48px] px-16 border rounded-input-10 text-left',
            open && !disabled && 'shadow-[0_0_0_3px_rgba(38,57,73,0.08)]',
            stateClass,
            bgClass,
            disabled ? 'cursor-not-allowed' : 'cursor-pointer'
          )}
        >
          <span className={cn('flex-1 min-w-0 text-body-sm-16 font-regular truncate', textClass)}>
            {value ?? placeholder}
          </span>
          <Icon
            name="calendar_today"
            size={24}
            filled
            className={disabled ? 'text-neutral-500' : 'text-neutral-black'}
          />
        </button>
        {open && !disabled && (
          <div
            style={{ zIndex: DROPDOWN_Z }}
            className="absolute left-0 right-0 top-full mt-4 bg-neutral-white border border-neutral-200 rounded-input-10 shadow-md p-16 flex flex-col gap-12"
          >
            <div className="flex items-center justify-between">
              <button
                type="button"
                onClick={() => moveMonth(-1)}
                aria-label="이전 달"
                className="p-4"
              >
                <Icon name="chevron_left" size={24} />
              </button>
              <span className="text-body-sm-16 font-semibold text-neutral-black">
                {viewYear}-{pad(viewMonth + 1)}
              </span>
              <button
                type="button"
                onClick={() => moveMonth(1)}
                aria-label="다음 달"
                className="p-4"
              >
                <Icon name="chevron_right" size={24} />
              </button>
            </div>
            <div className="grid grid-cols-7 gap-4">
              {DAY_LABELS.map((d) => (
                <span
                  key={d}
                  className="text-micro-14 font-medium text-neutral-500 text-center py-4"
                >
                  {d}
                </span>
              ))}
              {cells.map((c, i) => {
                if (!c.inMonth) return <span key={i} />;
                const iso = formatIso(viewYear, viewMonth, c.day);
                const isSelected = iso === value;
                return (
                  <button
                    key={i}
                    type="button"
                    onClick={() => {
                      onChange?.(iso);
                      setOpen(false);
                    }}
                    className={cn(
                      'aspect-square rounded-pill-999 text-body-sm-16 font-regular flex items-center justify-center',
                      isSelected
                        ? 'bg-primary text-neutral-white'
                        : 'text-neutral-black hover:bg-neutral-100'
                    )}
                  >
                    {c.day}
                  </button>
                );
              })}
            </div>
          </div>
        )}
      </div>
    );
  }
);

DatePicker.displayName = 'IDS.DatePicker';
