import { forwardRef } from 'react';
import { Icon } from '../Icon';
import type { PhotoThumbnailProps } from './PhotoThumbnail.types';

import { cn } from '../../internal/cn';

/**
 * PhotoThumbnail.
 *
 * Figma 정의 (node 0:434 small variant):
 *   - 정사각형, border neutral-200, radius 12
 *   - 사진 50% opacity over black bg
 *   - 우상단 delete 버튼 (icon-only, 20x20 padded)
 */
export const PhotoThumbnail = forwardRef<HTMLDivElement, PhotoThumbnailProps>(
  function PhotoThumbnail(
    { width, full, src, onDelete, className, style, ...rest },
    ref
  ) {
    return (
      <div
        ref={ref}
        className={cn(
          'relative overflow-clip aspect-square bg-neutral-black border border-neutral-200 rounded-lg-12',
          full ? 'w-full' : 'self-start',
          className
        )}
        style={{ width, ...style }}
        {...rest}
      >
        <img
          alt=""
          src={src}
          className="absolute inset-0 size-full object-cover opacity-50 pointer-events-none"
        />
        {onDelete && (
          <button
            type="button"
            onClick={onDelete}
            aria-label="삭제"
            className="absolute top-0 right-0 inline-flex items-center justify-center p-8 rounded-md-8 text-neutral-white"
          >
            <Icon name="delete" size={24} filled />
          </button>
        )}
      </div>
    );
  }
);

PhotoThumbnail.displayName = 'IDS.PhotoThumbnail';
