import { useEffect, useState, type ReactNode } from 'react';
import { createPortal } from 'react-dom';
import { Button } from '../Button/Button';
import { StepIndicator } from '../StepIndicator';
import { IDS_Z_INDEX } from '../../internal/zIndex';
import type { ModalEntry } from './Modal.types';
import { useModalStore } from './modalStore';

import { cn } from '../../internal/cn';

export const ModalRoot = () => {
  const stack = useModalStore((s) => s.stack);
  const closeById = useModalStore((s) => s.closeById);
  const [mounted, setMounted] = useState(false);

  useEffect(() => setMounted(true), []);
  if (!mounted || stack.length === 0) return null;

  return createPortal(
    <>
      {stack.map((entry, idx) => (
        <ModalLayer
          key={entry.id}
          entry={entry}
          zIndex={IDS_Z_INDEX.MODAL + idx}
          isTop={idx === stack.length - 1}
          onClose={(value) => closeById(entry.id, value)}
        />
      ))}
    </>,
    document.body
  );
};

interface LayerProps {
  entry: ModalEntry;
  zIndex: number;
  isTop: boolean;
  onClose: (value?: boolean) => void;
}

const ModalLayer = ({ entry, zIndex, isTop, onClose }: LayerProps) => {
  const { options } = entry;

  const titleGroup: ReactNode = (
    <div className="flex flex-col gap-8">
      {options.stepIndicator && (
        <StepIndicator
          total={options.stepIndicator.total}
          current={options.stepIndicator.current}
        />
      )}
      {options.infoMessage && (
        <span className="text-micro-14 font-regular text-neutral-600">
          {options.infoMessage}
        </span>
      )}
      <h2
        className="text-h2-22 font-bold text-neutral-black m-0"
        style={{ lineHeight: 1.5 }}
      >
        {options.title}
      </h2>
      {options.subtitle && (
        <p
          className="text-body-lg-18 font-regular text-neutral-black m-0 whitespace-pre-line"
          style={{ lineHeight: 1.5 }}
        >
          {options.subtitle}
        </p>
      )}
    </div>
  );

  const header = options.content ? (
    <div className="flex flex-col gap-16">
      {titleGroup}
      <div>{options.content}</div>
    </div>
  ) : (
    titleGroup
  );

  const tone = options.tone === 'danger' ? 'danger' : 'primary';

  return (
    <div
      className="fixed inset-0 flex items-center justify-center px-16"
      style={{ zIndex }}
      aria-hidden={!isTop}
    >
      <div
        className="absolute inset-0 bg-neutral-black/50"
        onClick={() => onClose(false)}
      />
      <div
        role="dialog"
        aria-modal="true"
        className={cn(
          'relative w-full max-w-[372px] bg-neutral-white rounded-lg-12 shadow-xl',
          'flex flex-col gap-32 pt-24 pb-16 px-16'
        )}
      >
        {header}
        <div className="flex gap-8">
          {entry.kind === 'confirm' && (
            <Button
              variant={entry.options.cancelTone === 'danger' ? 'danger' : 'secondary'}
              size="lg"
              className="flex-1"
              onClick={() => onClose(false)}
            >
              {entry.options.cancelLabel ?? '취소'}
            </Button>
          )}
          <Button
            variant={tone}
            size="lg"
            className="flex-1"
            onClick={() => onClose(true)}
          >
            {options.confirmLabel ?? '확인'}
          </Button>
        </div>
      </div>
    </div>
  );
};
