import { forwardRef, type CSSProperties, type ElementType } from 'react';
import { cn } from '../../../internal/cn';
import type { BoxProps } from './Box.types';
import type { SpacingToken } from '../../../types';

const P: Record<SpacingToken, string> = {
  0: 'p-0', 4: 'p-4', 8: 'p-8', 12: 'p-12', 16: 'p-16',
  24: 'p-24', 32: 'p-32', 48: 'p-48', 64: 'p-64',
};
const PX: Record<SpacingToken, string> = {
  0: 'px-0', 4: 'px-4', 8: 'px-8', 12: 'px-12', 16: 'px-16',
  24: 'px-24', 32: 'px-32', 48: 'px-48', 64: 'px-64',
};
const PY: Record<SpacingToken, string> = {
  0: 'py-0', 4: 'py-4', 8: 'py-8', 12: 'py-12', 16: 'py-16',
  24: 'py-24', 32: 'py-32', 48: 'py-48', 64: 'py-64',
};
const PT: Record<SpacingToken, string> = {
  0: 'pt-0', 4: 'pt-4', 8: 'pt-8', 12: 'pt-12', 16: 'pt-16',
  24: 'pt-24', 32: 'pt-32', 48: 'pt-48', 64: 'pt-64',
};
const PB: Record<SpacingToken, string> = {
  0: 'pb-0', 4: 'pb-4', 8: 'pb-8', 12: 'pb-12', 16: 'pb-16',
  24: 'pb-24', 32: 'pb-32', 48: 'pb-48', 64: 'pb-64',
};
const PL: Record<SpacingToken, string> = {
  0: 'pl-0', 4: 'pl-4', 8: 'pl-8', 12: 'pl-12', 16: 'pl-16',
  24: 'pl-24', 32: 'pl-32', 48: 'pl-48', 64: 'pl-64',
};
const PR: Record<SpacingToken, string> = {
  0: 'pr-0', 4: 'pr-4', 8: 'pr-8', 12: 'pr-12', 16: 'pr-16',
  24: 'pr-24', 32: 'pr-32', 48: 'pr-48', 64: 'pr-64',
};
const M: Record<SpacingToken, string> = {
  0: 'm-0', 4: 'm-4', 8: 'm-8', 12: 'm-12', 16: 'm-16',
  24: 'm-24', 32: 'm-32', 48: 'm-48', 64: 'm-64',
};
const MX: Record<SpacingToken, string> = {
  0: 'mx-0', 4: 'mx-4', 8: 'mx-8', 12: 'mx-12', 16: 'mx-16',
  24: 'mx-24', 32: 'mx-32', 48: 'mx-48', 64: 'mx-64',
};
const MY: Record<SpacingToken, string> = {
  0: 'my-0', 4: 'my-4', 8: 'my-8', 12: 'my-12', 16: 'my-16',
  24: 'my-24', 32: 'my-32', 48: 'my-48', 64: 'my-64',
};
const MT: Record<SpacingToken, string> = {
  0: 'mt-0', 4: 'mt-4', 8: 'mt-8', 12: 'mt-12', 16: 'mt-16',
  24: 'mt-24', 32: 'mt-32', 48: 'mt-48', 64: 'mt-64',
};
const MB: Record<SpacingToken, string> = {
  0: 'mb-0', 4: 'mb-4', 8: 'mb-8', 12: 'mb-12', 16: 'mb-16',
  24: 'mb-24', 32: 'mb-32', 48: 'mb-48', 64: 'mb-64',
};
const ML: Record<SpacingToken, string> = {
  0: 'ml-0', 4: 'ml-4', 8: 'ml-8', 12: 'ml-12', 16: 'ml-16',
  24: 'ml-24', 32: 'ml-32', 48: 'ml-48', 64: 'ml-64',
};
const MR: Record<SpacingToken, string> = {
  0: 'mr-0', 4: 'mr-4', 8: 'mr-8', 12: 'mr-12', 16: 'mr-16',
  24: 'mr-24', 32: 'mr-32', 48: 'mr-48', 64: 'mr-64',
};

export const Box = forwardRef<HTMLElement, BoxProps>(function Box(
  {
    as: Tag = 'div',
    padding,
    paddingX,
    paddingY,
    paddingTop,
    paddingBottom,
    paddingLeft,
    paddingRight,
    margin,
    marginX,
    marginY,
    marginTop,
    marginBottom,
    marginLeft,
    marginRight,
    width,
    height,
    minWidth,
    maxWidth,
    minHeight,
    maxHeight,
    full,
    fullHeight,
    grow,
    className,
    style,
    children,
    ...rest
  },
  ref
) {
  const classes = cn(
    padding !== undefined && P[padding],
    paddingX !== undefined && PX[paddingX],
    paddingY !== undefined && PY[paddingY],
    paddingTop !== undefined && PT[paddingTop],
    paddingBottom !== undefined && PB[paddingBottom],
    paddingLeft !== undefined && PL[paddingLeft],
    paddingRight !== undefined && PR[paddingRight],
    margin !== undefined && M[margin],
    marginX !== undefined && MX[marginX],
    marginY !== undefined && MY[marginY],
    marginTop !== undefined && MT[marginTop],
    marginBottom !== undefined && MB[marginBottom],
    marginLeft !== undefined && ML[marginLeft],
    marginRight !== undefined && MR[marginRight],
    full && 'w-full',
    fullHeight && 'h-full',
    grow && 'grow',
    className
  );

  const sizingStyle: CSSProperties = {
    ...(width !== undefined && { width }),
    ...(height !== undefined && { height }),
    ...(minWidth !== undefined && { minWidth }),
    ...(maxWidth !== undefined && { maxWidth }),
    ...(minHeight !== undefined && { minHeight }),
    ...(maxHeight !== undefined && { maxHeight }),
  };

  const Component = Tag as ElementType;
  return (
    <Component
      ref={ref}
      className={classes}
      style={{ ...sizingStyle, ...style }}
      {...rest}
    >
      {children}
    </Component>
  );
});
